function [m] = torque2dipole(tau, b, m_max)
%TORQUE2DIPOLE  The dipole across the field that gives the torque request: m = B x tau/|B|^2, saturated; no
%   field (|B|^2 < 1e-18), no dipole.
%   tau: real[1][3] (passed a plain number)
%   b: real[1][3] (passed a plain number)
%   m_max: real[1] (passed a plain number)
%   returns m: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 1);
    bs = (b(1)*b(1) + b(2)*b(2) + b(3)*b(3));
    if (bs < 1e-18)
        m = zeros(3, 1);
    else
        m = asils.alg.control.sat_dipole(([b(2)*tau(3) - b(3)*tau(2); b(3)*tau(1) - b(1)*tau(3); b(1)*tau(2) - b(2)*tau(1)] * (1 / bs)), m_max);
    end
end
